package ru.neverland.townycompanies;

import java.nio.charset.StandardCharsets;
import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.*;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.core.*;
import ru.neverland.townycompanies.api.CompanyPayrollApi;
import static ru.neverland.townycompanies.CompanyData.*;

/** Durable work offers are replayed into the existing company payment ledger by the same UUID. */
public final class CompanyPayroll implements CompanyPayrollApi,Listener,AutoCloseable {
    private final JavaPlugin plugin;private final CompanyService service;private final CompanyPayrollStore store;private final List<Double> multipliers;
    private final Map<UUID,UUID> submitting=new HashMap<>();private final Set<UUID> updating=new HashSet<>();private final long maximumRate;private int cursor;
    public CompanyPayroll(JavaPlugin plugin,CompanyService service)throws Exception{this.plugin=plugin;this.service=service;maximumRate=cents(plugin.getConfig().getString("payroll.maximum-rate","100.00"));multipliers=plugin.getConfig().getDoubleList("payroll.level-multipliers");if(multipliers.size()!=5||multipliers.stream().anyMatch(n->!Double.isFinite(n)||n<1||n>1.2))throw new IllegalArgumentException("Множители компании должны быть в пределах 1.00–1.20");for(int i=1;i<5;i++)if(multipliers.get(i)<multipliers.get(i-1))throw new IllegalArgumentException("Множители должны возрастать");store=new CompanyPayrollStore(plugin.getDataFolder().toPath().resolve("payroll.sqlite"),ex->plugin.getLogger().log(java.util.logging.Level.SEVERE,"Зарплаты компании приостановлены. Сохранённые начисления требуют проверки",ex));Bukkit.getServicesManager().register(CompanyPayrollApi.class,this,plugin,ServicePriority.Normal);Bukkit.getPluginManager().registerEvents(this,plugin);SuiteScheduler.get().runTaskTimer(plugin,this::tick,20,20);}
    public boolean obligations(UUID company){return !store.healthy()||submitting.containsValue(company)||store.outstanding().stream().anyMatch(w->w.company().equals(company));}
    @Override public void recordWork(Player p,UUID proof,String profession,int level){try(var guard=SuiteState.guard()){
        if(!store.healthy()||SuiteState.frozen(plugin.getName())||!plugin.getConfig().getBoolean("payroll.enabled",true)||!p.hasPermission("neverlandtownycompanies.salary")||!p.hasPermission("neverlandtownycompanies.use")||!SuiteScheduler.owns(p)||(p.getGameMode()!=GameMode.SURVIVAL&&p.getGameMode()!=GameMode.ADVENTURE))return;
        Company c=service.ledger.membership(p.getUniqueId());var town=CompanyService.town(p.getUniqueId());if(c==null||town==null||!town.getUUID().equals(c.town())||!service.active(c)||c.debt()>0||System.currentTimeMillis()>=c.nextTax())return;
        UUID id=UUID.nameUUIDFromBytes(("company-work:"+p.getUniqueId()+":"+proof).getBytes(StandardCharsets.UTF_8));if(submitting.containsKey(id))return;submitting.put(id,c.id());
        store.offer(id,c.id(),p.getUniqueId(),profession,level,System.currentTimeMillis(),multipliers).whenComplete((ok,error)->SuiteScheduler.get().runTask(plugin,()->submitting.remove(id)));
    }}
    private void tick(){try(var guard=SuiteState.guard()){if(!store.healthy()||!com.palmergames.bukkit.towny.TownyEconomyHandler.isActive())return;var work=store.outstanding();if(work.isEmpty())return;int begin=cursor%work.size(),count=Math.min(32,work.size());cursor=(begin+count)%work.size();for(int i=0;i<count;i++){var w=work.get((begin+i)%work.size());if(updating.contains(w.id()))continue;try{
        Payment payment=service.ledger.state().payments().get(w.id());if(payment==null){Company c=service.ledger.company(w.company());if(c==null||c.closed()){mark(w,"REJECTED");continue;}if(service.ledger.busy(c.id())||c.balance()<w.cents()||c.debt()>0||System.currentTimeMillis()>=c.nextTax())continue;payment=service.ledger.begin(w.id(),w.company(),w.employee(),Purpose.SALARY,w.cents(),w.created());}
        if(payment.purpose()!=Purpose.SALARY||!payment.company().equals(w.company())||!payment.account().equals(w.employee())||payment.amount()!=w.cents())throw new IllegalStateException("Условия начисления не совпадают: "+w.id());
        if(payment.phase()==Phase.READY)service.ledger.process(payment.id());payment=service.ledger.state().payments().get(w.id());String state=switch(payment.phase()){case DONE->"DONE";case REJECTED->"REJECTED";case PENDING->"REVIEW";case READY->"OFFERED";};if(!state.equals(w.state()))mark(w,state);
    }catch(Exception ex){plugin.getLogger().severe("Начисление "+w.id()+" ожидает проверки: "+ex.getMessage());break;}}}}
    private void mark(CompanyPayrollStore.Work w,String state){updating.add(w.id());store.state(w.id(),state).whenComplete((done,error)->SuiteScheduler.get().runTask(plugin,()->updating.remove(w.id())));}
    private Company owner(Player p){Company c=service.manage(p,true,true);if(!p.hasPermission("neverlandtownycompanies.payroll"))throw new IllegalArgumentException("Нет разрешения на настройку зарплат");if(!store.healthy())throw new IllegalArgumentException("Зарплаты компании сейчас недоступны");return c;}
    public void configure(Player p,String action,String profession,long amount){Company c=owner(p);var old=store.settings(c.id());boolean enabled=old.enabled();long budget=old.budget();var rates=new HashMap<>(old.rates());switch(action){case "on"->enabled=true;case "off"->enabled=false;case "budget"->budget=amount;case "rate"->{if(!CompanyPayrollStore.PROFESSIONS.contains(profession)||amount>maximumRate)throw new IllegalArgumentException("Ставка за действие: от 0 до "+format(maximumRate)+" монет");rates.put(profession,amount);}default->throw new IllegalArgumentException("Неизвестная настройка зарплаты");}if(enabled&&(budget==0||rates.values().stream().noneMatch(n->n>0)))throw new IllegalArgumentException("Сначала задайте бюджет и хотя бы одну ставку");var next=new CompanyPayrollStore.Settings(c.id(),enabled,budget,rates,old.revision()+1);UUID actor=p.getUniqueId();store.configure(next,old.revision()).whenComplete((done,error)->SuiteScheduler.get().runTask(plugin,()->{if(error==null)AuditTrail.record(plugin,"settings",c.id()+":"+next.revision(),"COMPANY_PAYROLL_SETTINGS","COMPLETED",AuditTrail.player(actor),AuditTrail.town(c.town()),new AuditRecord.Party("COMPANY",c.id().toString(),c.name(),c.town().toString()),"",0,"","enabled="+next.enabled()+"; budget="+format(next.budget())+"; rates="+next.rates());SuiteScheduler.player(plugin,p,ignored->p.sendMessage(error==null?"§aУсловия зарплат сохранены":"§eУсловия не сохранены: "+error.getMessage()));}));}
    public void open(Player p){service.requireUse(p);Company c=service.own(p);if(!store.healthy())throw new IllegalArgumentException("Раздел зарплат сейчас недоступен");var cfg=store.settings(c.id());View v=new View(p.getUniqueId());v.inventory=MenuStyle.inventory(plugin,v,54,"Зарплаты компании");v.inventory.setItem(4,icon(Material.GOLD_INGOT,c.name(),List.of("Баланс предприятия: "+format(c.balance()),"Начисления: "+(cfg.enabled()?"включены":"выключены"),"Лимит начислений за 24 ч.: "+format(cfg.budget()),"Ожидают выплаты: "+store.outstanding().stream().filter(w->w.company().equals(c.id())).count(),"Оплачиваются только действия на рабочей смене")));int slot=10;for(String profession:CompanyPayrollStore.PROFESSIONS)v.inventory.setItem(slot++,icon(Material.EMERALD,title(profession),List.of("За действие I уровня: "+format(cfg.rates().getOrDefault(profession,0L)),"Уровень профессии: множитель до "+multipliers.get(4))));if(c.owner().equals(p.getUniqueId())){v.inventory.setItem(29,icon(Material.WRITABLE_BOOK,"Настроить ставки и лимит",List.of("/company payroll rate <профессия> <сумма>","/company payroll budget <сумма>","Новая ставка применяется к будущим действиям")));v.inventory.setItem(31,icon(cfg.enabled()?Material.RED_DYE:Material.LIME_DYE,cfg.enabled()?"Остановить новые начисления":"Включить новые начисления",List.of("Уже заработанное останется в очереди")));v.toggle=cfg.enabled()?"off":"on";}v.inventory.setItem(33,icon(Material.BOOK,"Последние начисления",List.of("Получатели, суммы и состояние выплат")));v.inventory.setItem(49,icon(Material.ARROW,"Назад в компанию",List.of()));p.openInventory(v.inventory);}
    private void history(Player p){Company c=service.own(p);store.history(c.id()).whenComplete((work,error)->SuiteScheduler.player(plugin,p,ignored->{if(error!=null){p.sendMessage(ru.neverland.core.EditableMessages.text(CompanyPayroll.class, "§eЖурнал сейчас недоступен"));return;}Company current=service.own(p);if(!current.id().equals(c.id()))return;View v=new View(p.getUniqueId());v.inventory=MenuStyle.inventory(plugin,v,54,"Начисления сотрудникам");int slot=0;for(var w:work)v.inventory.setItem(slot++,icon(w.state().equals("DONE")?Material.LIME_DYE:Material.PAPER,service.residentName(w.employee()),List.of(title(w.profession())+" • уровень "+w.level(),"Сумма: "+format(w.cents()),"Статус: "+status(w.state()),"Дата: "+CompanyMenus.date(w.created()),"Квитанция: "+w.id())));v.history=true;v.inventory.setItem(49,icon(Material.ARROW,"Назад к зарплатам",List.of()));p.openInventory(v.inventory);}));}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof View v))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!v.owner.equals(p.getUniqueId())||e.getRawSlot()<0||e.getRawSlot()>=v.inventory.getSize())return;int slot=e.getRawSlot();SuiteScheduler.player(plugin,p,ignored->{try{if(slot==49)p.performCommand(v.history?"company payroll":"company");else if(!v.history&&slot==33)history(p);else if(!v.history&&slot==31&&v.toggle!=null){v.toggle=null;p.performCommand("company payroll "+(store.settings(service.own(p).id()).enabled()?"off":"on"));}else if(slot==29)p.sendMessage("§e/company payroll rate blacksmith 1.00\n/company payroll budget 1000\nПрофессии: "+String.join(", ",CompanyPayrollStore.PROFESSIONS));}catch(Exception ex){p.sendMessage("§e"+ex.getMessage());}});}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof View)e.setCancelled(true);}
    public static String title(String profession){return switch(profession){case "blacksmith"->"Кузнец";case "farmer"->"Фермер";case "engineer"->"Инженер";case "guard"->"Стражник";case "merchant"->"Торговец";case "researcher"->"Исследователь";case "alchemist"->"Алхимик";default->profession;};}
    private static String status(String state){return switch(state){case "DONE"->"Выплачено";case "REJECTED"->"Отклонено, средства остались компании";case "REVIEW"->"Нужна сверка банка";default->"Ожидает средств и выплаты";};}
    private static ItemStack icon(Material type,String name,List<String> lore){var item=new ItemStack(type);var meta=item.getItemMeta();meta.displayName(MenuStyle.nameComponent(MenuStyle.decode(name)));meta.lore(MenuStyle.loreComponents(lore.stream().map(MenuStyle::decode).toList()));meta.addItemFlags(ItemFlag.values());item.setItemMeta(meta);return item;}
    private static final class View implements InventoryHolder{final UUID owner;Inventory inventory;String toggle;boolean history;View(UUID owner){this.owner=owner;}public Inventory getInventory(){return inventory;}}
    public CompanyPayrollStore store(){return store;}
    public java.util.concurrent.CompletionStage<Void> prepareClose(){store.close();return store.stopped();}
    public void close(){prepareClose();}
}
